arguments.file_text:
/* GridForge Stylesheet - Modern, Clean & Local */
:root {
  --primary-color: #2563eb;
  --primary-hover: #1d4ed8;
  --bg-color: #f8fafc;
  --panel-bg: #ffffff;
  --border-color: #e2e8f0;
  --border-dark: #cbd5e1;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --header-bg: #f1f5f9;
  --cell-selected-bg: rgba(37, 99, 235, 0.08);
  --cell-selected-border: #2563eb;
  --cell-ref-border: #8b5cf6;
  --danger-color: #ef4444;
  --success-color: #10b981;
  --warning-color: #f59e0b;
  --cell-width: 100px;
  --cell-height: 28px;
  --header-height: 28px;
  --row-header-width: 48px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-size: 13px;
  color: var(--text-main);
  background: var(--bg-color);
  overflow: hidden;
  height: 100vh;
  display: flex;
  flex-direction: column;
}

/* App Header */
.app-header {
  background: var(--panel-bg);
  border-bottom: 1px solid var(--border-color);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  gap: 16px;
}

.brand-section {
  display: flex;
  align-items: center;
  gap: 12px;
}

.logo-badge {
  background: var(--primary-color);
  color: #fff;
  font-weight: 700;
  font-size: 14px;
  padding: 4px 8px;
  border-radius: 4px;
  letter-spacing: 0.5px;
}

.workbook-title-box {
  display: flex;
  flex-direction: column;
}

.workbook-title {
  font-size: 16px;
  font-weight: 600;
  color: var(--text-main);
}

.sheet-badge {
  font-size: 11px;
  color: var(--text-muted);
}

.toolbar-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Toolbar Buttons & Inputs */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  padding: 6px 12px;
  font-size: 12px;
  font-weight: 500;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background: var(--panel-bg);
  color: var(--text-main);
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, color 0.15s;
  user-select: none;
}

.btn:hover:not(:disabled) {
  background: #f1f5f9;
  border-color: var(--border-dark);
}

.btn:focus-visible {
  outline: 2px solid var(--primary-color);
  outline-offset: 1px;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.btn-primary {
  background: var(--primary-color);
  color: #fff;
  border-color: var(--primary-color);
}

.btn-primary:hover:not(:disabled) {
  background: var(--primary-hover);
  border-color: var(--primary-hover);
}

.btn-danger {
  background: var(--danger-color);
  color: #fff;
  border-color: var(--danger-color);
}

.btn-sm {
  padding: 4px 8px;
  font-size: 11px;
}

/* Status Indicator */
.save-status {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  padding: 4px 8px;
  border-radius: 4px;
  background: #f8fafc;
  border: 1px solid var(--border-color);
  white-space: nowrap;
}

.save-status.saved {
  color: var(--success-color);
}

.save-status.unsaved {
  color: var(--warning-color);
}

.save-status.saving {
  color: var(--primary-color);
}

.save-status.error {
  color: var(--danger-color);
}

/* User & Presence Section */
.collaboration-section {
  display: flex;
  align-items: center;
  gap: 12px;
}

.user-selector-container {
  display: flex;
  align-items: center;
  gap: 6px;
}

.user-select {
  padding: 5px 8px;
  font-size: 12px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background: #fff;
  color: var(--text-main);
  cursor: pointer;
}

.user-select:focus-visible {
  outline: 2px solid var(--primary-color);
}

.user-avatar-badge {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 10px;
  font-weight: 700;
}

/* Presence Legend */
.presence-legend {
  display: flex;
  align-items: center;
  gap: 6px;
  border-left: 1px solid var(--border-color);
  padding-left: 12px;
}

.presence-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 12px;
  font-size: 11px;
  font-weight: 500;
  color: #fff;
}

/* Toolbar & Formula Bar */
.formula-bar-container {
  background: var(--panel-bg);
  border-bottom: 1px solid var(--border-color);
  padding: 4px 12px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.name-box {
  width: 90px;
  padding: 5px 8px;
  font-size: 12px;
  font-weight: 600;
  text-align: center;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background: #fff;
  color: var(--text-main);
}

.name-box:focus {
  outline: 2px solid var(--primary-color);
}

.fx-label {
  font-style: italic;
  font-weight: bold;
  color: var(--text-muted);
  font-size: 14px;
  user-select: none;
  padding: 0 4px;
}

.formula-input {
  flex: 1;
  padding: 5px 8px;
  font-family: inherit;
  font-size: 13px;
  border: 1px solid var(--border-color);
  border-radius: 4px;
  background: #fff;
  color: var(--text-main);
}

.formula-input:focus {
  outline: 2px solid var(--primary-color);
}

/* Preview Alert Banner */
.preview-banner {
  display: none;
  background: #fef3c7;
  color: #92400e;
  border-bottom: 1px solid #fde68a;
  padding: 6px 16px;
  align-items: center;
  justify-content: space-between;
  font-size: 12px;
  font-weight: 500;
}

.preview-banner.active {
  display: flex;
}

/* Main Grid Container */
.grid-wrapper {
  flex: 1;
  position: relative;
  overflow: auto;
  background: #fff;
  outline: none;
}

/* Spreadsheet Table */
.spreadsheet-table {
  border-collapse: separate;
  border-spacing: 0;
  table-layout: fixed;
  background: #fff;
}

.corner-header {
  position: sticky;
  top: 0;
  left: 0;
  z-index: 30;
  width: var(--row-header-width);
  min-width: var(--row-header-width);
  max-width: var(--row-header-width);
  height: var(--header-height);
  background: var(--header-bg);
  border-right: 1px solid var(--border-dark);
  border-bottom: 1px solid var(--border-dark);
  cursor: pointer;
}

.col-header {
  position: sticky;
  top: 0;
  z-index: 20;
  height: var(--header-height);
  width: var(--cell-width);
  min-width: var(--cell-width);
  max-width: var(--cell-width);
  background: var(--header-bg);
  border-right: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-dark);
  font-weight: 600;
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
  vertical-align: middle;
  user-select: none;
  cursor: pointer;
}

.col-header.highlighted {
  background: #e2e8f0;
  color: var(--primary-color);
  font-weight: 700;
}

.row-header {
  position: sticky;
  left: 0;
  z-index: 10;
  width: var(--row-header-width);
  min-width: var(--row-header-width);
  max-width: var(--row-header-width);
  height: var(--cell-height);
  background: var(--header-bg);
  border-right: 1px solid var(--border-dark);
  border-bottom: 1px solid var(--border-color);
  font-weight: 600;
  font-size: 11px;
  color: var(--text-muted);
  text-align: center;
  vertical-align: middle;
  user-select: none;
  cursor: pointer;
}

.row-header.highlighted {
  background: #e2e8f0;
  color: var(--primary-color);
  font-weight: 700;
}

/* Grid Cells */
.grid-cell {
  width: var(--cell-width);
  min-width: var(--cell-width);
  max-width: var(--cell-width);
  height: var(--cell-height);
  max-height: var(--cell-height);
  border-right: 1px solid var(--border-color);
  border-bottom: 1px solid var(--border-color);
  padding: 0 6px;
  font-size: 12px;
  vertical-align: middle;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: cell;
  user-select: none;
  position: relative;
}

.grid-cell.cell-number {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.grid-cell.cell-text {
  text-align: left;
}

.grid-cell.cell-error {
  color: var(--danger-color);
  font-weight: 600;
  background: #fef2f2;
}

.grid-cell.selected-range {
  background-color: var(--cell-selected-bg);
}

.grid-cell.active-cell {
  background-color: #fff;
}

.grid-cell.conflict-cell {
  background-color: #fef3c7 !important;
  box-shadow: inset 0 0 0 2px var(--warning-color);
}

.grid-cell.ref-highlight-0 {
  box-shadow: inset 0 0 0 2px #3b82f6;
  background-color: rgba(59, 130, 246, 0.08);
}
.grid-cell.ref-highlight-1 {
